/* claude-green-timestamp */
;(function(){
  if (window.__claudeGreenTimestampInstalled) return;
  window.__claudeGreenTimestampInstalled = true;
  function tag() {
    var nodes = document.querySelectorAll('[data-testid="assistant-message"] p:not(.claude-ts-line)');
    for (var i=0; i<nodes.length; i++) {
      var p = nodes[i];
      var t = (p.textContent || '').replace(/^[\s\u00a0]+/, '');
      if (t.indexOf('\u{1F4EC} ') === 0) {
        p.classList.add('claude-ts-line');
      }
    }
  }
  function init() {
    tag();
    new MutationObserver(tag).observe(document.body, {childList: true, subtree: true, characterData: true});
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
/* /claude-green-timestamp */
